package mz.gov.mogovolas.expedientes.repository; import mz.gov.mogovolas.expedientes.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface ExpedienteRepository extends JpaRepository<Expediente,Long>{long countByEstado(Expediente.EstadoExpediente e); long countByPrioridade(Expediente.Prioridade p); @Query("select e from Expediente e where lower(e.numero) like lower(concat('%',:q,'%')) or lower(e.assunto) like lower(concat('%',:q,'%')) or lower(coalesce(e.remetente,'')) like lower(concat('%',:q,'%')) order by e.dataEntrada desc") List<Expediente> pesquisar(@Param("q") String q); List<Expediente> findByEstado(Expediente.EstadoExpediente e);}
